/bin/bash -lc "python - <<'PY'
import mujoco
from sim import build_spec
model=build_spec().compile();
for i in range(model.ngeom):
    nm=mujoco.mj_id2name(model,mujoco.mjtObj.mjOBJ_GEOM,i)
    if not nm: continue
    if any(k in nm.lower() for k in ['finger','fingertip','hand','panda','cup','table','floor']):
        print(i,nm,'body',mujoco.mj_id2name(model,mujoco.mjtObj.mjOBJ_BODY, model.geom_bodyid[i]))
print('bodies:')
for i in range(model.nbody):
    nm=mujoco.mj_id2name(model,mujoco.mjtObj.mjOBJ_BODY,i)
    if nm:
        print(i,nm)
print('body 9 hand joint positions with zero ctrl after init:')
import sim
s=sim.Sim();
# print ee pos, hand/body/geom positions
bid= s.model.body_name2id('hand') if hasattr(s.model,'body_name2id') else mujoco.mj_name2id(s.model,mujoco.mjtObj.mjOBJ_BODY,'hand')
print('hand body id',bid,'xpos',s.data.xpos[bid])
for i in range(s.model.ngeom):
    nm=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_GEOM,i)
    if nm and 'finger' in nm.lower():
        print('finger geom',nm,'xpos',s.data.xpos[i+0])
PY"

